
import { useEffect, useRef, useState } from 'react'
import { Html5Qrcode } from 'html5-qrcode'
import { supabase } from './services/supabase'

export default function QRScanner() {
  const scannerRef = useRef<Html5Qrcode | null>(null)
    const processingRef = useRef(false)

      const [scanning, setScanning] = useState(false)
        const [message, setMessage] = useState('')
          const [result, setResult] = useState('')

            async function stopScanner() {
                const scanner = scannerRef.current

                    if (scanner) {
                          try {
                                  if (scanner.isScanning) {
                                            await scanner.stop()
                                                    }
                                                            await scanner.clear()
                                                                  } catch (error) {
                                                                          console.log('Kamera dihentikan')
                                                                                }

                                                                                      scannerRef.current = null
                                                                                          }

                                                                                              setScanning(false)
                                                                                                }

                                                                                                  async function startScanner() {
                                                                                                      setMessage('')
                                                                                                          setResult('')
                                                                                                              processingRef.current = false

                                                                                                                  try {
                                                                                                                        const scanner = new Html5Qrcode('qr-reader')
                                                                                                                              scannerRef.current = scanner

                                                                                                                                    await scanner.start(
                                                                                                                                            { facingMode: 'environment' },
                                                                                                                                                    {
                                                                                                                                                              fps: 10,
                                                                                                                                                                        qrbox: { width: 250, height: 250 }
                                                                                                                                                                                },
                                                                                                                                                                                        async (decodedText) => {
                                                                                                                                                                                                  if (processingRef.current) return

                                                                                                                                                                                                            processingRef.current = true
                                                                                                                                                                                                                      setMessage('QR berhasil dibaca. Memproses absensi...')

                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                            const { data, error } = await supabase.rpc(
                                                                                                                                                                                                                                                          'submit_qr_attendance',
                                                                                                                                                                                                                                                                        { p_token: decodedText }
                                                                                                                                                                                                                                                                                    )

                                                                                                                                                                                                                                                                                                if (error) throw error

                                                                                                                                                                                                                                                                                                            if (data?.status === 'present') {
                                                                                                                                                                                                                                                                                                                          setResult('HADIR')
                                                                                                                                                                                                                                                                                                                                      } else if (data?.status === 'late') {
                                                                                                                                                                                                                                                                                                                                                    setResult('TERLAMBAT')
                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                              setResult(data?.status || 'BERHASIL')
                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                      setMessage(data?.message || 'Absensi berhasil dicatat.')
                                                                                                                                                                                                                                                                                                                                                                                                                } catch (error: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                            setResult('')
                                                                                                                                                                                                                                                                                                                                                                                                                                        setMessage(error.message || 'Absensi gagal diproses.')
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            await stopScanner()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            () => {}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setScanning(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (error: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  scannerRef.current = null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setScanning(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setMessage(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Kamera tidak dapat dibuka. Pastikan izin kamera sudah diberikan. ' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (error.message || '')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useEffect(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const scanner = scannerRef.current

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (scanner?.isScanning) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    scanner.stop().catch(() => {})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, [])

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <section style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: '#ffffff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  padding: '20px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        borderRadius: '12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              marginBottom: '20px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: '1px solid #e5e7eb'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2>Absensi Guru</h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Silakan pindai QR permanen yang tersedia di gerbang madrasah.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                id="qr-reader"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  width: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maxWidth: '400px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      margin: '15px auto'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {!scanning ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={startScanner}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  background: '#166534',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: 'white',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: '12px 20px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  borderRadius: '8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width: '100%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Buka Kamera dan Scan QR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={stopScanner}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: '#b91c1c',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: 'white',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: '12px 20px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: '8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: '100%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Hentikan Kamera
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {message && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p style={{ marginTop: '15px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {message}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {result && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h3 style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: result === 'HADIR' ? '#166534' : '#b45309',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              textAlign: 'center'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                STATUS: {result}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    